== submit.js
// Self-check your MP3 against the course autograder.
//
// 1. Deploy your API (e.g. on Render) and set API_URL below to its base URL.
// 2. Run:  npm run submit    (or: node submit.js)
//
// The autograder cannot reach localhost, so API_URL must be your deployed URL.
// Requires Node 24 (LTS).

const API_URL = "https://YOUR-APP-NAME.onrender.com"; // <-- change this to your deployed API's URL

// Grader URL; DO NOT CHANGE.
const AUTOGRADER_URL = "https://cs409-mp3-grader.onrender.com";

const TIMEOUT_MS = 6 * 60 * 1000; // a free-tier Render app may need a minute to wake up

function fail(message) {
    console.error(`\n${message}\n`);
    process.exit(1);
}

async function main() {
    if (API_URL.includes("YOUR-APP-NAME")) {
        fail("Please edit API_URL at the top of submit.js to your deployed API URL.");
    }
    if (AUTOGRADER_URL.includes("REPLACE-WITH")) {
        fail("AUTOGRADER_URL has not been configured. Please contact the course staff.");
    }

    console.log(`Submitting ${API_URL} to the autograder...`);
    console.log("This can take a few minutes (the autograder runs many requests against your API).\n");

    let res;
    try {
        res = await fetch(`${AUTOGRADER_URL.replace(/\/+$/, "")}/grade`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ url: API_URL }),
            signal: AbortSignal.timeout(TIMEOUT_MS),
        });
    } catch (e) {
        fail(`Could not reach the autograder (${e.name === "TimeoutError" ? "timed out" : e.message}). Try again in a minute.`);
    }

    let result;
    try {
        result = await res.json();
    } catch {
        fail(`The autograder returned an unexpected response (HTTP ${res.status}).`);
    }
    if (!res.ok) {
        fail(`Autograder error (HTTP ${res.status}): ${result.error || JSON.stringify(result)}`);
    }

    const label = { passed: "PASS   ", partial: "PARTIAL", failed: "FAIL   " };
    for (const t of result.tests) {
        console.log(`[${label[t.status] || t.status}] ${t.test}  (${t.awardedScore}/${t.possibleScore})`);
        for (const m of t.messages) console.log(`           - ${m}`);
    }
    console.log(`\nScore: ${result.score}/100  (${result.awardedPoints}/${result.totalPoints} points)\n`);
}

main();
== FAQ
## FAQ

Here are some answers to some popular questions from previous years.

### Lost In The Sauce?

* Where do I begin? 

    > I'm really confused on how to start or what to do for MP3?
    
    __Answer__: Please start by watching the dev lab recordings, as they often provide instructions on how to approach the MPs. Additionally, going through the class slides and recordings can give you a better understanding of the concepts. Lastly, ensure you thoroughly read through the MP3 instructions, as they are designed to guide you through the assignment. If after doing all these, you still have questions, please don't hesitate to reach out for further clarification. If you did all of that and are still confused, please join the next available office hours.

* Next Steps After Setting up MongoDB Cluster?

    > Confused on how to start. I've set up the mongodb cluster and everything but I don't know what to do next.

    __Answer__: The next step is to get the connection string. If you've set up the MongoDB cluster, Click on "Connect" to get the connection string. The connection string typically looks like:

    `mongodb+srv://[redacted-secret]@link/test?retryWrites=true`

    Replace <username> and <password> with your __database__ username and password. The database credentials are not the login details for your MongoDB Atlas account.

* Testing?

    > How to check if my code is correct? Just NPM start? What else should i do to check if my code can pass the tests?

    __Answer__: Once you implemented all 4 endpoints, you can use tools like Postman to manually test your API routes. Ensure that all endpoints return the expected response and status codes. Inspect the data in your database to ensure that the data gets stored, updated, and deleted as intended based on your API actions.

