cat > routes/helpers.js <<'EOF'
// Shared pieces for the users and tasks routes: the response envelope, an
// error type that carries an HTTP status, id checks, and query-string parsing.

class HttpError extends Error {
    constructor(status, message) {
        super(message);
        this.status = status;
    }
}

function respond(res, status, message, data) {
    res.status(status).json({ message: message, data: data === undefined ? null : data });
}

var OBJECT_ID = /^[0-9a-fA-F]{24}$/;
function isValidId(value) {
    return typeof value === 'string' && OBJECT_ID.test(value);
}

function isNonEmptyString(value) {
    return typeof value === 'string' && value.trim().length > 0;
}

function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseJsonParam(raw, name) {
    if (raw === undefined) return undefined;
    var value;
    try {
        value = JSON.parse(raw);
    } catch (e) {
        throw new HttpError(400, 'Query parameter "' + name + '" is not valid JSON');
    }
    if (!isPlainObject(value)) {
        throw new HttpError(400, 'Query parameter "' + name + '" must be a JSON object');
    }
    return value;
}

function parseIntParam(raw, name) {
    if (raw === undefined) return undefined;
    if (!/^\d+$/.test(String(raw).trim())) {
        throw new HttpError(400, 'Query parameter "' + name + '" must be a non-negative integer');
    }
    return parseInt(raw, 10);
}

// Parses where/sort/select/skip/limit/count. Only the first value of a
// repeated parameter is used.
function parseListQuery(query, options) {
    var first = function (name) { return Array.isArray(query[name]) ? query[name][0] : query[name]; };
    var countRaw = first('count');
    var count;
    if (countRaw === undefined) count = false;
    else if (countRaw === 'true' || countRaw === '1') count = true;
    else if (countRaw === 'false' || countRaw === '0' || countRaw === '') count = false;
    else throw new HttpError(400, 'Query parameter "count" must be true or false');
    return {
        where: parseJsonParam(first('where'), 'where') || {},
        sort: parseJsonParam(first('sort'), 'sort'),
        select: parseJsonParam(first('select'), 'select'),
        skip: parseIntParam(first('skip'), 'skip'),
        limit: parseIntParam(first('limit'), 'limit') !== undefined
            ? parseIntParam(first('limit'), 'limit')
            : options.defaultLimit,
        count: count
    };
}

function parseSelect(query) {
    return parseJsonParam(Array.isArray(query.select) ? query.select[0] : query.select, 'select');
}

// Runs a list query against a model and returns the documents or the count.
async function runListQuery(Model, params) {
    if (params.count) {
        return Model.countDocuments(params.where);
    }
    var query = Model.find(params.where);
    if (params.sort) query = query.sort(params.sort);
    if (params.select) query = query.select(params.select);
    if (params.skip) query = query.skip(params.skip);
    if (params.limit !== undefined && params.limit !== null) query = query.limit(params.limit);
    return query.exec();
}

// Errors MongoDB/Mongoose raise for malformed filters, sorts or projections
// are the client's fault, not the server's.
function isBadQueryError(err) {
    if (!err) return false;
    if (err.name === 'CastError' || err.name === 'ValidationError') return true;
    if (err.name === 'MongoServerError' && [2, 31253, 31254, 15975, 15976, 51175, 4772600].indexOf(err.code) >= 0) return true;
    return false;
}

// Wraps an async route so rejections become JSON error responses.
function wrap(handler) {
    return function (req, res, next) {
        Promise.resolve(handler(req, res, next)).catch(next);
    };
}

module.exports = {
    HttpError: HttpError,
    respond: respond,
    isValidId: isValidId,
    isNonEmptyString: isNonEmptyString,
    isPlainObject: isPlainObject,
    parseListQuery: parseListQuery,
    parseSelect: parseSelect,
    runListQuery: runListQuery,
    isBadQueryError: isBadQueryError,
    wrap: wrap
};
EOF
cat > routes/users.js <<'EOF'
var User = require('../models/user');
var Task = require('../models/task');
var h = require('./helpers');

// Checks a user body. Returns { name, email, pendingTasks } or throws 400.
function validateUserBody(body) {
    if (!h.isPlainObject(body)) throw new h.HttpError(400, 'Request body must be a JSON object');
    if (!h.isNonEmptyString(body.name)) throw new h.HttpError(400, 'A user needs a name');
    if (!h.isNonEmptyString(body.email)) throw new h.HttpError(400, 'A user needs an email');
    var pendingTasks = body.pendingTasks === undefined || body.pendingTasks === null ? [] : body.pendingTasks;
    if (!Array.isArray(pendingTasks)) throw new h.HttpError(400, 'pendingTasks must be a list of task ids');
    pendingTasks.forEach(function (id) {
        if (!h.isValidId(id)) throw new h.HttpError(400, 'pendingTasks contains an invalid task id');
    });
    // Duplicates in the list are harmless; keep the first occurrence of each.
    pendingTasks = pendingTasks.filter(function (id, i) { return pendingTasks.indexOf(id) === i; });
    return { name: body.name, email: body.email, pendingTasks: pendingTasks };
}

async function ensureEmailFree(email, ownId) {
    var filter = { email: email };
    if (ownId) filter._id = { $ne: ownId };
    if (await User.exists(filter)) throw new h.HttpError(400, 'A user with this email already exists');
}

// Loads the tasks named in pendingTasks; 404 if one is missing, 400 if one is completed.
async function loadPendingTasks(ids) {
    if (ids.length === 0) return [];
    var tasks = await Task.find({ _id: { $in: ids } });
    if (tasks.length !== ids.length) throw new h.HttpError(404, 'A task in pendingTasks does not exist');
    tasks.forEach(function (task) {
        if (task.completed) throw new h.HttpError(400, 'A completed task cannot be in pendingTasks');
    });
    return tasks;
}

// Assigns the given tasks to the user, moving them away from other users.
async function assignTasks(tasks, user) {
    var ids = tasks.map(function (t) { return String(t._id); });
    if (ids.length === 0) return;
    await User.updateMany(
        { _id: { $ne: user._id }, pendingTasks: { $in: ids } },
        { $pull: { pendingTasks: { $in: ids } } }
    );
    await Task.updateMany(
        { _id: { $in: ids } },
        { $set: { assignedUser: String(user._id), assignedUserName: user.name } }
    );
}

async function unassignTasks(ids) {
    if (ids.length === 0) return;
    await Task.updateMany(
        { _id: { $in: ids } },
        { $set: { assignedUser: '', assignedUserName: 'unassigned' } }
    );
}

module.exports = function (router) {
    router.route('/users')
        .get(h.wrap(async function (req, res) {
            var params = h.parseListQuery(req.query, { defaultLimit: undefined });
            var data = await h.runListQuery(User, params);
            h.respond(res, 200, 'OK', data);
        }))
        .post(h.wrap(async function (req, res) {
            var fields = validateUserBody(req.body);
            await ensureEmailFree(fields.email);
            var tasks = await loadPendingTasks(fields.pendingTasks);
            var user = await User.create(fields);
            await assignTasks(tasks, user);
