            if (!user) throw new h.HttpError(404, 'User not found');
            await Task.updateMany(
                { assignedUser: String(user._id) },
                { $set: { assignedUser: '', assignedUserName: 'unassigned' } }
            );
            await user.deleteOne();
            h.respond(res, 200, 'User deleted', user);
        }));

    return router;
};
